def secondary(manifest, runs, records, keys, coverage, methods, seed):
    from analysis.methods.decisions import native_vector
    from analysis.methods.pipeline import confidence_for_run, stability
    out = {}
    for cid in DECISIONS:
        config_methods = methods.get('decision_models', {}).get(cid, {})
        reviewed = config_methods.get('probability_semantics_verified') is True
        def reader(row, policy, provenance):
            if not reviewed:
                return None, 'probability_fields_unreviewed'
            values, reason = native_vector(row, sum_tolerance='0.02')
            return ({k: v/sum(values.values()) for k, v in values.items()}, None) if values else (None, reason)
        primary = next(r for r in runs if r['config_id'] == cid and r['role'] == 'primary')
        policy = 'native_selected_normalized_distribution'
        conf = confidence_for_run(manifest, primary, records, keys, policy,
            methods={'probability_semantics_verified': reviewed, 'bootstrap_seed': seed},
            complete=all((manifest['benchmark'], manifest['split'], q['item_id'], cid, primary['run_id']) in records for q in manifest['items']),
            vector_reader=reader)
        scalar_fields = list(dict.fromkeys(config_methods.get('scalar_fields', ['concentration'] if cid == 'D01' else ['provider_confidence']) + [field for row in records.values() if row['identity']['config_id'] == cid for field in row.get('provider_scalars', {})]))
        if not scalar_fields or len(set(scalar_fields)) != len(scalar_fields):
            raise ValueError('Supply distinct native scalar fields')
        def scalar_records(field):
            meaning = config_methods.get('scalar_semantics', {}).get(field)
            historical = (cid, field) in {('D01', 'concentration'), ('D02', 'provider_confidence')}
            if historical or (isinstance(meaning, str) and meaning.strip().lower() not in ('', 'unreviewed', 'unknown')):
                return records
            return {key: {**row, 'probability': {**row['probability'], field: None,
                        field+'_reason': 'scalar_semantics_unreviewed'}}
                    if row['identity']['config_id'] == cid else row for key, row in records.items()}
        repeat = stability(manifest, runs, scalar_records(scalar_fields[0]), keys, coverage, policy, config_id=cid,
                           scalar_field=scalar_fields[0], vector_reader=reader)
        if not all(r['complete'] for r in repeat.get('runs', {}).values()):
            repeat.pop('answer_flows', None)
        repeat['provider_scalars'] = {}
        for field in scalar_fields:
            part = repeat if field == scalar_fields[0] else stability(manifest, runs, scalar_records(field), keys, coverage,
                policy, config_id=cid, scalar_field=field, vector_reader=reader)
            repeat['provider_scalars'][field] = {'pairs': [
                {'earlier_run': p['earlier_run'], 'later_run': p['later_run'],
                 **p['confidence_change_distribution']['provider_scalar']} for p in part.get('pairs', [])],
                'three_way': part.get('confidence_three_way', {}).get('provider_scalar'),
                'semantics': config_methods.get('scalar_semantics', {}).get(field, 'source-specific native field')}
        out[cid] = {'confidence': conf, 'stability': repeat, 'sum_tolerance': '0.02',
                    'probability_semantics_verified': reviewed}
    return out

